effect.shader:
float ruido(vec2 p) {
    return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453);
}

float canalComRastro(vec2 uv, vec2 dir, float raio, int canal, int n) {
    float soma = 0.0;
    for (int i = 0; i <= 24; i++) {
        if (i > n) break;
        float t = float(i) / float(n) - 0.5;
        soma += texture(inputImg, uv + dir * raio * t)[canal];
    }
    return soma / float(n + 1);
}

void main() {
    vec4 original = texture(inputImg, acScreenNorm);

    float linha = floor(acScreenNorm.y * sliceCount);
    float deslocamento = (ruido(vec2(linha, seed + floor(acTime * 8.0))) - 0.5) * 2.0 * sliceAmount;

    vec2 uv = acScreenNorm + vec2(deslocamento, 0.0);
    vec2 dirRastro = vec2(sign(deslocamento + 1e-5), 0.0);
    int n = clamp(int(samples), 2, 24);

    float r = canalComRastro(uv + vec2( rgbSplit, 0.0), dirRastro, blurAmount, 0, n);
    float g = canalComRastro(uv,                           dirRastro, blurAmount, 1, n);
    float b = canalComRastro(uv + vec2(-rgbSplit, 0.0), dirRastro, blurAmount, 2, n);

    fragColor = vec4(r, g, b, original.a);
}
